-- EldoUI Map Notes: the City services pack. Class and profession
-- trainers, weapon masters, bankers, auctioneers, flight masters and
-- innkeepers in capitals and towns, on the world map and the minimap, with
-- one tick per kind (Map Notes > City services).
--
-- Where they stand comes from EldoUI_LootData's Services.lua (CMaNGOS
-- classic-db, GPL-3.0, generated by tools/lootdata/gen_lootdata.py; the GPL
-- data stays in that folder). This file only reads it, like the Classic
-- rares group does, and needs the Loot Guide with its data loaded.
--
-- Side: the data names each NPC's faction template, not its side. The side
-- of a template is worked out from the zones its NPCs stand in (Zone Info's
-- faction territory, Data/Zones.lua; contested zones don't count): seen only in Alliance zones = Alliance,
-- only in Horde zones = Horde, anything else counts for both sides.
--
-- WoW: Forever changes: SERVICES_FOREVER below holds our own facts
-- (Apache-2.0) about towns Forever changed, checked in game: `hide` drops a
-- Classic NPC, `add` places a new one. Nothing is listed until someone has
-- checked a changed town in the client.
--
-- Presentation only: static places from the data; nothing is clicked,
-- targeted or sent for the player.
local _, E = ...
local L = E.L

local M = E:GetModule("MapNotes")
if not M then return end

local issecret = issecretvalue or function() return false end

local KINDS = { "class", "profession", "weapon", "bank", "auction", "flight", "inn" }
M.SERVICE_KINDS = KINDS
local LETTER = { c = "class", p = "profession", w = "weapon", b = "bank", a = "auction", f = "flight", i = "inn" }
-- Shown translated: L["Class trainer"], L["Profession trainer"], L["Weapon master"], L["Banker"],
-- L["Auctioneer"], L["Flight master"], L["Innkeeper"]
local TITLE = {
	class = "Class trainer", profession = "Profession trainer", weapon = "Weapon master", bank = "Banker",
	auction = "Auctioneer", flight = "Flight master", inn = "Innkeeper",
}
M.SERVICE_TITLE = TITLE
-- The game's map icon where the client has it, else a plain icon.
local ICON = {
	class = { texture = "Interface\\Icons\\INV_Misc_Book_11" },
	profession = { atlas = "Profession", texture = "Interface\\Icons\\INV_Misc_Note_01" },
	weapon = { texture = "Interface\\Icons\\INV_Sword_04" },
	bank = { atlas = "Banker", texture = "Interface\\Icons\\INV_Misc_Bag_10_Blue" },
	auction = { atlas = "Auctioneer", texture = "Interface\\Icons\\INV_Misc_Coin_02" },
	flight = { atlas = "TaxiNode_Neutral", texture = "Interface\\Icons\\Ability_Mount_Gryphon_01" },
	inn = { atlas = "Innkeeper", texture = "Interface\\Icons\\INV_Misc_Rune_01" },
}
M.SERVICE_ICON = ICON

-- Our own WoW: Forever facts (see the header).
--   hide[npcID] = true
--   add = { { kind = "bank", uiMapID = 1453, x = 0.5, y = 0.5, name = "...", service = "..." } }
M.SERVICES_FOREVER = M.SERVICES_FOREVER or { hide = {}, add = {} }

M.defaults.services = {
	class = true, profession = true, weapon = true, bank = true, auction = true, flight = true, inn = true,
	myFaction = true,
}

local function Settings()
	return M.db and M.db.services or M.defaults.services
end

---------------------------------------------------------------------------
-- The index: uiMapID -> records, built once the data is loaded
---------------------------------------------------------------------------
local index, sides

function M:ClearServiceCache()
	index, sides = nil, nil
end

local function Data()
	local LG = M.LootGuide and M.LootGuide()
	local LD = LG and rawget(_G, "EldoUI_LootData")
	if type(LD) == "table" and type(LD.services) == "table" then return LG, LD end
end

-- "kinds|factionTemplate|map|x,y,z,count;...|name|subname"
local function Parse(text)
	if type(text) ~= "string" then return end
	local kinds, faction, map, camps, name, sub = text:match("^(%a+)|(%d+)|(%d+)|([^|]*)|([^|]*)|?(.*)$")
	if not kinds then return end
	return kinds, tonumber(faction), tonumber(map), camps, name, sub
end
M.ParseService = Parse

local function ZoneSide(uiMapID)
	local zone = E.zoneData and E.zoneData.zones and E.zoneData.zones[uiMapID]
	local side = type(zone) == "table" and zone.faction
	return (side == "Alliance" or side == "Horde") and side or nil
end

local function Build()
	local LG, LD = Data()
	if not LD then return nil end
	index, sides = {}, {}
	local votes = {}
	local english = not GetLocale or GetLocale() == "enUS" or GetLocale() == "enGB"
	local names = LD.L and LD.L.mobs
	for npc, text in pairs(LD.services) do
		local letters, faction, map, camps, name, sub = Parse(text)
		if letters and map then
			local kinds = {}
			for letter in letters:gmatch(".") do
				if LETTER[letter] then kinds[LETTER[letter]] = true end
			end
			local camp = 0
			for x, y in (camps or ""):gmatch("(%-?[%d%.]+),(%-?[%d%.]+),[^;]*") do
				camp = camp + 1
				if camp > 3 then break end
				local uiMapID, px, py = LG:MapPosition({ map = map, x = tonumber(x), y = tonumber(y) })
				if uiMapID and px and px >= 0 and px <= 1 and py >= 0 and py <= 1 then
					local list = index[uiMapID] or {}
					index[uiMapID] = list
					list[#list + 1] = {
						npc = npc, camp = camp, kinds = kinds, faction = faction, x = px, y = py,
						name = type(names) == "table" and type(names[npc]) == "string" and names[npc] or name,
						-- The subname ("Mage Trainer") names the service only for a one-service NPC.
						sub = english and sub ~= "" and #letters == 1 and sub or nil,
					}
					local side = ZoneSide(uiMapID)
					if side and faction then
						votes[faction] = votes[faction] or { Alliance = 0, Horde = 0 }
						votes[faction][side] = votes[faction][side] + 1
					end
				end
			end
		end
	end
	for faction, count in pairs(votes) do
		if count.Alliance > 0 and count.Horde == 0 then
			sides[faction] = "Alliance"
		elseif count.Horde > 0 and count.Alliance == 0 then
			sides[faction] = "Horde"
		end
	end
	for _, list in pairs(index) do
		table.sort(list, function(a, b) if a.npc ~= b.npc then return a.npc < b.npc end return a.camp < b.camp end)
	end
	return index
end

-- The side a faction template belongs to, or nil (both sides).
function M:ServiceSide(faction)
	if not sides then Build() end
	return sides and sides[faction] or nil
end

local function PlayerSide()
	local side = UnitFactionGroup and UnitFactionGroup("player")
	if issecret(side) then return nil end
	return (side == "Alliance" or side == "Horde") and side or nil
end

-- Flight masters already show through Transport Maps when it is on.
local function TransportShowsFlights()
	local transport = E.Transport
	return transport and transport.active and transport.db and transport.db.kinds and transport.db.kinds.flight and true or false
end
M.TransportShowsFlights = TransportShowsFlights

local function Shown(kinds, settings, skipFlight)
	local list = {}
	for _, kind in ipairs(KINDS) do
		if kinds[kind] and settings[kind] and not (kind == "flight" and skipFlight) then list[#list + 1] = kind end
	end
	return list
end

local function Line(shown, sub)
	if sub and #shown == 1 then return sub end
	local parts = {}
	for _, kind in ipairs(shown) do parts[#parts + 1] = L[TITLE[kind]] end
	return table.concat(parts, ", ")
end


function M:ServicePoints(uiMapID)
	local out = {}
	if type(uiMapID) ~= "number" then return out end
	if not index then Build() end
	local settings = Settings()
	local mine = settings.myFaction and PlayerSide()
	local skipFlight = TransportShowsFlights()
	local overlay = M.SERVICES_FOREVER or {}
	local hide = type(overlay.hide) == "table" and overlay.hide or {}
	for _, rec in ipairs(index and index[uiMapID] or {}) do
		local side = sides and sides[rec.faction]
		if not hide[rec.npc] and not (mine and side and side ~= mine) then
			local shown = Shown(rec.kinds, settings, skipFlight)
			if #shown > 0 then
				out[#out + 1] = {
					key = ("%d:%d"):format(rec.npc, rec.camp), kind = "service", x = rec.x, y = rec.y,
					label = rec.name, service = Line(shown, rec.sub), icon = ICON[shown[1]],
					note = L["Classic position from the Loot Guide's data; WoW: Forever may differ."],
				}
			end
		end
	end
	for number, add in ipairs(type(overlay.add) == "table" and overlay.add or {}) do
		if type(add) == "table" and add.uiMapID == uiMapID and ICON[add.kind] and settings[add.kind]
			and not (add.kind == "flight" and skipFlight) and type(add.x) == "number" and type(add.y) == "number" then
			out[#out + 1] = {
				key = "forever:" .. number, kind = "service", x = add.x, y = add.y, label = add.name,
				service = add.service or L[TITLE[add.kind]], icon = ICON[add.kind],
				note = L["WoW: Forever position, checked in game."],
			}
		end
	end
	return out
end

-- Zone and city maps only: on a continent the services of every town would
-- cover the whole map.
M:RegisterPack("services", {
	title = "City services", kind = "service", continent = "never",
	points = function(uiMapID) return M:ServicePoints(uiMapID) end,
})

---------------------------------------------------------------------------
-- Options: Map Notes > City services
---------------------------------------------------------------------------
local rows = {
	{ type = "tab", label = L["City services"] },
	{ type = "description", label = L["Trainers, bankers, the auction house, flight masters and innkeepers in towns, on the world map and minimap. Needs the Loot Guide's data."] },
	{ type = "header", label = L["Show"] },
	{ type = "toggle", key = "services.class", label = L["Class trainers"], desc = L["Trainers for your class's spells, and pet trainers."] },
	{ type = "toggle", key = "services.profession", label = L["Profession trainers"], desc = L["Trainers for crafting and gathering professions, cooking, fishing and first aid."] },
	{ type = "toggle", key = "services.weapon", label = L["Weapon masters"], desc = L["Trainers who teach weapon skills."] },
	{ type = "toggle", key = "services.bank", label = L["Bankers"], desc = L["Where you reach your bank."] },
	{ type = "toggle", key = "services.auction", label = L["Auction house"], desc = L["Auctioneers."] },
	{ type = "toggle", key = "services.flight", label = L["Flight masters"], desc = L["Flight masters. While Transport Maps shows flight masters, they come from there instead, so each shows once."] },
	{ type = "toggle", key = "services.inn", label = L["Innkeepers"], desc = L["Where you can set your hearthstone."] },
	{ type = "toggle", key = "services.myFaction", label = L["Only my faction"], desc = L["Hide the other faction's services. Neutral towns, and NPCs whose side the data can't tell, always show."] },
}
for _, row in ipairs(rows) do table.insert(M.options, row) end
